{
  "Count": 104,
  "Tools": [
    {
      "Name": "app_about",
      "Description": "显示关于对话框",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "app_get",
      "Description": "读应用配置项;不带参数列出全部\n示例: app.get key=console.history",
      "InputSchema": {
        "type": "object",
        "properties": {
          "key": {
            "type": "string",
            "description": "配置键;省略列出全部"
          }
        }
      }
    },
    {
      "Name": "app_opendata",
      "Description": "在系统资源管理器中打开应用数据目录",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "app_set",
      "Description": "写应用配置项\n示例: app.set key=console.history value=1000",
      "InputSchema": {
        "type": "object",
        "properties": {
          "key": {
            "type": "string",
            "description": "配置键"
          },
          "value": {
            "type": "string",
            "description": "配置值"
          }
        },
        "required": [
          "key",
          "value"
        ]
      }
    },
    {
      "Name": "cls",
      "Description": "清空控制台显示(不清日志文件)",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "command_domains",
      "Description": "列出全部指令域及注册数量\n示例: command.domains",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "command_list",
      "Description": "结构化列出全部注册指令及其来源、风险和 MCP 投影\n示例: command.list domain=proj mcp=visible filter=scan",
      "InputSchema": {
        "type": "object",
        "properties": {
          "domain": {
            "type": "string",
            "description": "可选指令域，如 proj / attr / command"
          },
          "mcp": {
            "type": "string",
            "description": "按当前策略过滤 MCP 可见性",
            "default": "all",
            "enum": [
              "all",
              "visible",
              "hidden"
            ]
          },
          "filter": {
            "type": "string",
            "description": "按名称、说明或来源搜索"
          }
        }
      }
    },
    {
      "Name": "command_manual",
      "Description": "从运行时注册表和 MCP 投影预览或生成 Markdown 命令手册\n示例: command.manual file=command-manual.md apply=false\n⚠ 危险操作:调用会请求宿主端人工确认(mcp.confirm=host),批准后才执行。",
      "InputSchema": {
        "type": "object",
        "properties": {
          "file": {
            "type": "string",
            "description": "相对当前工作目录的 Markdown 输出路径"
          },
          "apply": {
            "type": "boolean",
            "description": "false 仅预览；true 经本地确认后原子写入",
            "default": false
          }
        },
        "required": [
          "file"
        ]
      }
    },
    {
      "Name": "command_show",
      "Description": "查看单条指令的 Help 参数、来源、风险和 MCP 映射\n示例: command.show name=mcp.apply",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "完整指令名"
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "correction_list",
      "Description": "列出 MCP 工具描述勘误记录\n示例: correction.list name=proj.list limit=20",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "可选指令名"
          },
          "limit": {
            "type": "integer",
            "description": "最多返回条数",
            "default": 50
          }
        }
      }
    },
    {
      "Name": "correction_propose",
      "Description": "提交工具描述勘误，不直接修改生效描述\n示例: correction.propose name=proj.list claim=\"扫描全部磁盘\" correction=\"只列已登记工作树\"",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "指令名或工具名"
          },
          "claim": {
            "type": "string",
            "description": "需要纠正的原说法"
          },
          "correction": {
            "type": "string",
            "description": "正确解释"
          },
          "evidence": {
            "type": "string",
            "description": "证据或复现记录"
          },
          "proposal": {
            "type": "string",
            "description": "可选关联的提示词提案 ID"
          }
        },
        "required": [
          "name",
          "claim",
          "correction"
        ]
      }
    },
    {
      "Name": "db_delete",
      "Description": "删除行(无 where 将清空整表,需二次确认)\n示例: db.delete table=users where=\"id=1032\"\n⚠ 危险操作:调用会请求宿主端人工确认(mcp.confirm=host),批准后才执行。",
      "InputSchema": {
        "type": "object",
        "properties": {
          "table": {
            "type": "string",
            "description": "表名(db.tables 可查)"
          },
          "where": {
            "type": "string",
            "description": "SQL 条件;省略 = 清空整表(危险)"
          },
          "conn": {
            "type": "string",
            "description": "连接名,缺省 main(db.list 可查)"
          }
        },
        "required": [
          "table"
        ]
      }
    },
    {
      "Name": "db_export",
      "Description": "导出查询结果为 CSV 文件\n示例: db.export table=users file=用户.csv where=\"vip=1\"",
      "InputSchema": {
        "type": "object",
        "properties": {
          "table": {
            "type": "string",
            "description": "表名(db.tables 可查)"
          },
          "file": {
            "type": "string",
            "description": "目标文件;相对路径落到工作区目录"
          },
          "where": {
            "type": "string",
            "description": "SQL 条件片段"
          },
          "conn": {
            "type": "string",
            "description": "连接名,缺省 main(db.list 可查)"
          }
        },
        "required": [
          "table",
          "file"
        ]
      }
    },
    {
      "Name": "db_insert",
      "Description": "插入一行\n示例: db.insert table=users set=\"name='张三', age=30\"",
      "InputSchema": {
        "type": "object",
        "properties": {
          "table": {
            "type": "string",
            "description": "表名(db.tables 可查)"
          },
          "set": {
            "type": "string",
            "description": "列=值 列表,逗号分隔,字符串用单引号"
          },
          "conn": {
            "type": "string",
            "description": "连接名,缺省 main(db.list 可查)"
          }
        },
        "required": [
          "table",
          "set"
        ]
      }
    },
    {
      "Name": "db_list",
      "Description": "列出全部命名数据库连接",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "db_query",
      "Description": "查询表数据(表窗口同步显示结果)\n示例: db.query table=users where=\"age>30 and city='北京'\" limit=100",
      "InputSchema": {
        "type": "object",
        "properties": {
          "table": {
            "type": "string",
            "description": "表名(db.tables 可查)"
          },
          "where": {
            "type": "string",
            "description": "SQL 条件片段(原样拼接)"
          },
          "order": {
            "type": "string",
            "description": "SQL 排序片段,如 \"age desc\""
          },
          "limit": {
            "type": "integer",
            "description": "每页行数",
            "default": 500
          },
          "page": {
            "type": "integer",
            "description": "页码(1 起)",
            "default": 1
          },
          "conn": {
            "type": "string",
            "description": "连接名,缺省 main(db.list 可查)"
          }
        },
        "required": [
          "table"
        ]
      }
    },
    {
      "Name": "db_schema",
      "Description": "查看表结构(字段名 / 类型 / 主键 / 非空)\n示例: db.schema table=users",
      "InputSchema": {
        "type": "object",
        "properties": {
          "table": {
            "type": "string",
            "description": "表名(db.tables 可查)"
          },
          "conn": {
            "type": "string",
            "description": "连接名,缺省 main(db.list 可查)"
          }
        },
        "required": [
          "table"
        ]
      }
    },
    {
      "Name": "db_sql",
      "Description": "SQL 直通(高级用户;执行前有风险确认)\n示例: db.sql \"SELECT city, COUNT(*) FROM users GROUP BY city\"\n⚠ 危险操作:调用会请求宿主端人工确认(mcp.confirm=host),批准后才执行。",
      "InputSchema": {
        "type": "object",
        "properties": {
          "sql": {
            "type": "string",
            "description": "完整 SQL 语句"
          },
          "conn": {
            "type": "string",
            "description": "连接名,缺省 main(db.list 可查)"
          }
        },
        "required": [
          "sql"
        ]
      }
    },
    {
      "Name": "db_tables",
      "Description": "列出连接内全部表\n示例: db.tables",
      "InputSchema": {
        "type": "object",
        "properties": {
          "conn": {
            "type": "string",
            "description": "连接名,缺省 main"
          }
        }
      }
    },
    {
      "Name": "db_update",
      "Description": "更新行(无 where 将更新整表,需二次确认)\n示例: db.update table=users set=\"vip=1\" where=\"id=1032\"\n⚠ 危险操作:调用会请求宿主端人工确认(mcp.confirm=host),批准后才执行。",
      "InputSchema": {
        "type": "object",
        "properties": {
          "table": {
            "type": "string",
            "description": "表名(db.tables 可查)"
          },
          "set": {
            "type": "string",
            "description": "列=值 列表,逗号分隔"
          },
          "where": {
            "type": "string",
            "description": "SQL 条件;省略 = 整表更新(危险)"
          },
          "conn": {
            "type": "string",
            "description": "连接名,缺省 main(db.list 可查)"
          }
        },
        "required": [
          "table",
          "set"
        ]
      }
    },
    {
      "Name": "DemoModule_Add",
      "Description": "两个整数相加,返回和\n示例: DemoModule.Add a=1 b=1",
      "InputSchema": {
        "type": "object",
        "properties": {
          "a": {
            "type": "integer",
            "description": "第一个加数"
          },
          "b": {
            "type": "integer",
            "description": "第二个加数"
          }
        },
        "required": [
          "a",
          "b"
        ]
      }
    },
    {
      "Name": "DemoModule_Now",
      "Description": "返回当前时间和机器名(演示静态方法与对象返回值的 JSON 回显)\n示例: DemoModule.Now",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "DemoModule_Reverse",
      "Description": "把字符串反转\n示例: DemoModule.Reverse text=文本",
      "InputSchema": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string",
            "description": "要反转的字符串"
          }
        },
        "required": [
          "text"
        ]
      }
    },
    {
      "Name": "DemoModule_SayHello",
      "Description": "向指定的人问好(演示异步方法与默认参数)\n示例: DemoModule.SayHello name=文本",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "要问候的名字,缺省为 World",
            "default": "World"
          }
        }
      }
    },
    {
      "Name": "git_rule_gaps",
      "Description": "只列未纳管的格式与目录候选,按影响文件数降序(缺口清单)\n示例: git.rule.gaps",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "项目名;省略则查全库"
          }
        }
      }
    },
    {
      "Name": "git_rule_list",
      "Description": "列出项目根文件格式的纳入 Git、LFS、LF 规则和实际索引状态\n示例: git.rule.list name=0000-000-Template",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "已登记 Project 名/分支名"
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "git_rule_remove",
      "Description": "预览或确认后移除托管文件格式规则；不删除本地文件\n示例: git.rule.remove name=demo pattern=*.xlsx apply=false\n⚠ 危险操作:调用会请求宿主端人工确认(mcp.confirm=host),批准后才执行。",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "已登记 Project 名/分支名"
          },
          "pattern": {
            "type": "string",
            "description": "要移除的简单文件格式"
          },
          "apply": {
            "type": "boolean",
            "description": "false 仅预览；true 经本地确认后移除",
            "default": false
          }
        },
        "required": [
          "name",
          "pattern"
        ]
      }
    },
    {
      "Name": "git_rule_scan",
      "Description": "扫描项目库全部文件格式,输出台账与覆盖率(省略 name 扫全库)\n示例: git.rule.scan depth=normal",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "项目名;省略则扫描全库"
          },
          "deep": {
            "type": "boolean",
            "description": "true 时追加 git lfs 指针核验(较慢)",
            "default": false
          },
          "refresh": {
            "type": "boolean",
            "description": "true 时忽略缓存全量重扫",
            "default": false
          }
        }
      }
    },
    {
      "Name": "git_rule_set",
      "Description": "预览或确认后设置文件格式的纳入 Git、LFS、LF 状态并同步索引\n示例: git.rule.set name=demo pattern=*.xlsx track=true lfs=true lf=false apply=false\n⚠ 危险操作:调用会请求宿主端人工确认(mcp.confirm=host),批准后才执行。",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "已登记 Project 名/分支名"
          },
          "pattern": {
            "type": "string",
            "description": "简单文件格式，如 *.xlsx"
          },
          "track": {
            "type": "boolean",
            "description": "是否纳入 Git",
            "default": true
          },
          "lfs": {
            "type": "boolean",
            "description": "是否使用 LFS 指针",
            "default": false
          },
          "lf": {
            "type": "boolean",
            "description": "是否作为文本并统一 LF",
            "default": false
          },
          "apply": {
            "type": "boolean",
            "description": "false 仅预览；true 经本地确认后写入并同步索引",
            "default": false
          }
        },
        "required": [
          "name",
          "pattern"
        ]
      }
    },
    {
      "Name": "git_rule_suggest",
      "Description": "对未决格式给出处置建议(派生件忽略/文本 LF/大二进制 LFS;未知格式留白)\n示例: git.rule.suggest",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "项目名;省略则针对全库"
          }
        }
      }
    },
    {
      "Name": "git_rule_sync",
      "Description": "把模板项目的规则基线刷入各项目的 baseline 块(不动项目自身 managed 块与手写内容)\n示例: git.rule.sync apply=false\n⚠ 危险操作:调用会请求宿主端人工确认(mcp.confirm=host),批准后才执行。",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "目标项目;省略则同步全部项目(模板自身除外)"
          },
          "apply": {
            "type": "boolean",
            "description": "false 仅预览;true 经确认后写入",
            "default": false
          }
        }
      }
    },
    {
      "Name": "HelloWorld_Say",
      "Description": "返回固定问候文本，不产生任何外部副作用\n示例: HelloWorld.Say",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "help",
      "Description": "列出全部指令 / 显示某指令详情与示例\n示例: help win.dock",
      "InputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "指令名;省略时列出全部指令"
          }
        }
      }
    },
    {
      "Name": "history",
      "Description": "查看指令历史\n示例: history count=10",
      "InputSchema": {
        "type": "object",
        "properties": {
          "count": {
            "type": "integer",
            "description": "显示条数",
            "default": 20
          }
        }
      }
    },
    {
      "Name": "incident_list",
      "Description": "列出 MCP 工具调用或描述事故记录\n示例: incident.list name=proj.list limit=20",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "可选指令名"
          },
          "limit": {
            "type": "integer",
            "description": "最多返回条数",
            "default": 50
          }
        }
      }
    },
    {
      "Name": "incident_record",
      "Description": "记录工具调用或描述事故；保留预期、实际和证据\n示例: incident.record name=proj.list symptom=误解扫描范围 expected=只列登记项目 actual=尝试扫描磁盘",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "指令名或工具名"
          },
          "symptom": {
            "type": "string",
            "description": "问题现象"
          },
          "expected": {
            "type": "string",
            "description": "预期行为"
          },
          "actual": {
            "type": "string",
            "description": "实际行为"
          },
          "evidence": {
            "type": "string",
            "description": "日志、复现步骤或引用"
          },
          "correction": {
            "type": "string",
            "description": "可选关联的勘误 ID"
          }
        },
        "required": [
          "name",
          "symptom",
          "expected",
          "actual"
        ]
      }
    },
    {
      "Name": "layout_list",
      "Description": "列出全部命名布局方案",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "layout_load",
      "Description": "加载命名布局方案\n示例: layout.load name=调试布局",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "方案名(layout.list 可查)"
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "layout_reset",
      "Description": "重置为默认布局",
      "InputSchema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "Name": "layout_save",
      "Description": "把当前布局保存为命名方案\n示例: layout.save name=调试布局",
      "InputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "方案名"
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "Name": "log_level",
      "Description": "调整控制台日志显示级别(文件始终全量)\n示例: log.level warn",
      "InputSchema": {
        "type": "object",
        "properties": {
          "level": {
            "type": "string",
            "description": "显示级别;省略时查看当前值",
            "enum": [
              "trace",
              "debug",
              "info",
              "warn",
              "error",
              "fatal"
            ]
          }
        }
      }
    },
    {
      "Name": "module_dir",
      "Description": "查看/切换模块目录(切换后立即重载并持久化)\n示例: module.dir path=D:\\MyModules",
      "InputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "新模块目录(绝对路径);省略则只显示当前目录"
          }
        }
      }
    },
